import numpy as np
def fig_climograma():
    fig, ax = plt.subplots(figsize=(6.2, 3.0)); m = list(range(1, 13)); ll = [120,118,130,105,90,60,65,70,75,120,105,100]; tt = [24,23,21,17,14,11,10,12,14,17,20,23]
    ax.bar(m, ll, color="#6fa3cf"); ax.set_ylabel("lluvia (mm)", fontsize=8); ax.set_xticks(m); ax.set_xlabel("mes del año", fontsize=8); ax.tick_params(labelsize=7.5)
    a2 = ax.twinx(); a2.plot(m, tt, color="#c0392b", marker="o", ms=3); a2.set_ylabel("temperatura (°C)", fontsize=8, color="#c0392b"); a2.set_ylim(0, 30); a2.tick_params(labelsize=7.5)
    ax.set_title("Climograma de Buenos Aires (valores aproximados)", fontsize=9); return png(fig)
